bool snake1(const std::string &provided) {
  const std::size_t width = 9;
  const std::size_t height = 8;
  uint64_t target = 0;
  using row_t = std::array<char, width>;
  std::array<row_t, height> arr;
  uint64_t wanted = 0x5044644b5a667875;
  
  std::cerr << std::hex << 
    "&arr:	" << (void*)&arr << std::endl <<
    "&target:	" << (void*)&target << std::endl <<
    "&target - &arr:	" << std::dec << (std::ptrdiff_t)(void*)(&target) - (std::ptrdiff_t)(void*)(&arr) << std::endl;

  for (std::size_t pi = 0; pi < std::min(width * height, provided.size()); pi++) {
    std::size_t dest_row = pi / width;
    std::size_t dest_col = pi % width;
    if (0 == (dest_row % 2)) {
      dest_col = (width - (pi % width)) - 1;
    }

    arr[dest_row][dest_col] = provided[pi];
  }

  for (std::size_t row = 0; row < height; row++) {
    for (std::size_t col = 0; col < width; col++) {
      std::cerr << std::hex << arr[row][col];
    }
    std::cerr << std::endl;
  }

  std::cerr << "target: " << std::hex << target << std::endl;
  std::cerr << "wanted: " << std::hex << wanted << std::endl;

  return target == wanted;
}
